/// Returns true iff `r` and `x` share at least one common value.
///
/// Assumptions (per problem statement):
/// - `x` is sorted in non-decreasing order (duplicates allowed).
/// - `r` and `x` may be empty.
pub fn tangent(r: Vec<u64>, x: Vec<u64>) -> bool {
    if r.is_empty() || x.is_empty() {
        return false;
    }

    // Since `x` is sorted, check each element of `r` via binary search in `x`.
    // This guarantees correctness: we return true exactly when some value exists in both.
    for v in r {
        if x.binary_search(&v).is_ok() {
            return true;
        }
    }
    false
}

